"use client"

import * as React from "react"
import { Sign, type SignProps } from "@/components/ui/sign"
import type { SignShape } from "@/lib/0db/sign-shapes"

const shape: SignShape = {
  "word": "down",
  "line": [
    [
      [
        "M",
        12,
        5
      ],
      [
        "L",
        12,
        19
      ]
    ],
    [
      [
        "M",
        19,
        12
      ],
      [
        "L",
        12,
        19
      ]
    ],
    [
      [
        "M",
        12,
        19
      ],
      [
        "L",
        5,
        12
      ]
    ]
  ]
}

function SignArrowDownDots(props: Omit<SignProps, "shape" | "variant">) {
  return <Sign shape={shape} variant="dots" {...props} />
}

export { SignArrowDownDots, shape }
